-- Classic 1.60: vanilla quest money (VMaNGOS 1.12, generated by classic_re/classic_quest_money.py): reward (negative = the quest costs
-- that much) and the level 60 gold, for vanilla quests not taken from a Forever sniff. 4429 quests, 71 of them cost money.
CREATE TABLE IF NOT EXISTS `quest_classic_money` (
  `ID` int unsigned NOT NULL,
  `RewardMoney` int NOT NULL DEFAULT 0,
  `RewardMoneyMaxLevel` int unsigned NOT NULL DEFAULT 0,
  PRIMARY KEY (`ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Classic 1.60: vanilla quest money (VMaNGOS RewOrReqMoney, RewMoneyMaxLevel)';
DELETE FROM `quest_classic_money`;
